using Store;

namespace Store.Tests;

[TestClass]
public sealed class ShoppingCartTests
{
    private ShoppingCart _cart = null!;

    [TestInitialize]
    public void Setup() => _cart = new ShoppingCart();

    // ── AddItem ──────────────────────────────────────────────

    [TestMethod]
    public void AddItem_SingleItem_AppearsInCart()
    {
        _cart.AddItem("SKU-001", 2, 9.99m);

        Assert.Contains("SKU-001", _cart.Items.Keys);
        Assert.AreEqual(2, _cart.Items["SKU-001"].Quantity);
        Assert.AreEqual(9.99m, _cart.Items["SKU-001"].Price);
    }

    [TestMethod]
    public void AddItem_SameSkuTwice_CombinesQuantity()
    {
        _cart.AddItem("SKU-001", 2, 5.00m);
        _cart.AddItem("SKU-001", 3, 5.00m);

        Assert.AreEqual(5, _cart.Items["SKU-001"].Quantity);
    }

    [TestMethod]
    public void AddItem_MultipleDistinctSkus_AllPresent()
    {
        _cart.AddItem("A", 1, 10m);
        _cart.AddItem("B", 1, 20m);

        Assert.HasCount(2, _cart.Items);
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public void AddItem_NullOrWhiteSpaceSku_Throws(string? sku)
    {
        Assert.ThrowsExactly<ArgumentException>(() => _cart.AddItem(sku!, 1, 1m));
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-1)]
    public void AddItem_ZeroOrNegativeQuantity_Throws(int qty)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(() => _cart.AddItem("SKU", qty, 1m));
    }

    [TestMethod]
    public void AddItem_NegativePrice_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(() => _cart.AddItem("SKU", 1, -1m));
    }

    [TestMethod]
    public void AddItem_ZeroPrice_DoesNotThrow()
    {
        _cart.AddItem("FREE", 1, 0m);

        Assert.Contains("FREE", _cart.Items.Keys);
    }

    // ── RemoveItem ───────────────────────────────────────────

    [TestMethod]
    public void RemoveItem_ExistingItem_RemovesFromCart()
    {
        _cart.AddItem("SKU-001", 1, 5m);

        _cart.RemoveItem("SKU-001");

        Assert.IsEmpty(_cart.Items);
    }

    [TestMethod]
    public void RemoveItem_NonExistentSku_ThrowsKeyNotFound()
    {
        Assert.ThrowsExactly<KeyNotFoundException>(() => _cart.RemoveItem("MISSING"));
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("  ")]
    public void RemoveItem_NullOrWhiteSpaceSku_Throws(string? sku)
    {
        Assert.ThrowsExactly<ArgumentException>(() => _cart.RemoveItem(sku!));
    }

    [TestMethod]
    public void RemoveItem_OnlyRemovesTargetSku()
    {
        _cart.AddItem("A", 1, 10m);
        _cart.AddItem("B", 1, 20m);

        _cart.RemoveItem("A");

        Assert.DoesNotContain("A", _cart.Items.Keys);
        Assert.Contains("B", _cart.Items.Keys);
    }

    // ── CalculateTotal ───────────────────────────────────────

    [TestMethod]
    public void CalculateTotal_EmptyCart_ReturnsZero()
    {
        Assert.AreEqual(0m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_SingleItem_ReturnsQuantityTimesPrice()
    {
        _cart.AddItem("SKU", 3, 10.00m);

        Assert.AreEqual(30.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_MultipleItems_ReturnsSumOfLineItems()
    {
        _cart.AddItem("A", 2, 5.00m);   // 10
        _cart.AddItem("B", 1, 15.00m);  // 15

        Assert.AreEqual(25.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_AfterRemoval_ExcludesRemovedItem()
    {
        _cart.AddItem("A", 1, 10m);
        _cart.AddItem("B", 1, 20m);
        _cart.RemoveItem("A");

        Assert.AreEqual(20m, _cart.CalculateTotal());
    }

    // ── ApplyCoupon ──────────────────────────────────────────

    [TestMethod]
    [DataRow("SAVE10", 10)]
    [DataRow("SAVE20", 20)]
    [DataRow("HALF", 50)]
    public void ApplyCoupon_ValidCode_SetsDiscount(string code, int expectedPercent)
    {
        _cart.ApplyCoupon(code);

        Assert.AreEqual((decimal)expectedPercent, _cart.DiscountPercent);
    }

    [TestMethod]
    public void ApplyCoupon_CaseInsensitive_Accepted()
    {
        _cart.ApplyCoupon("save10");

        Assert.AreEqual(10m, _cart.DiscountPercent);
    }

    [TestMethod]
    public void ApplyCoupon_InvalidCode_ThrowsArgumentException()
    {
        var ex = Assert.ThrowsExactly<ArgumentException>(() => _cart.ApplyCoupon("BOGUS"));

        Assert.Contains("BOGUS", ex.Message);
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("  ")]
    public void ApplyCoupon_NullOrWhiteSpace_Throws(string? code)
    {
        Assert.ThrowsExactly<ArgumentException>(() => _cart.ApplyCoupon(code!));
    }

    // ── Coupon + Total integration ───────────────────────────

    [TestMethod]
    public void CalculateTotal_WithSave10Coupon_Applies10PercentDiscount()
    {
        _cart.AddItem("SKU", 1, 100m);
        _cart.ApplyCoupon("SAVE10");

        Assert.AreEqual(90m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_WithHalfCoupon_HalvesTotal()
    {
        _cart.AddItem("A", 2, 50m); // 100
        _cart.ApplyCoupon("HALF");

        Assert.AreEqual(50m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_CouponOnEmptyCart_ReturnsZero()
    {
        _cart.ApplyCoupon("SAVE20");

        Assert.AreEqual(0m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void ApplyCoupon_SecondCoupon_ReplacesFirst()
    {
        _cart.AddItem("SKU", 1, 100m);
        _cart.ApplyCoupon("SAVE10");
        _cart.ApplyCoupon("SAVE20");

        Assert.AreEqual(80m, _cart.CalculateTotal());
    }
}

